package com.bank.flink.mr;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Reproduces MATCH_RECOGNIZE PATTERN (A B+ C) per symbol, event-time ordered:
//   A = starting reference price
//   B+ = one or more ticks strictly below A
//   C = a tick back above A (recovery) -> emit match
class PatternMatcher {
    private static final Logger log = Logger.getLogger(PatternMatcher.class.getName());

    enum State { LOOKING_FOR_A, IN_B }

    private final String symbol;
    private State state = State.LOOKING_FOR_A;
    private BigDecimal aPrice;     // FIRST(A.price)
    private BigDecimal lowPrice;   // LAST(B.price) tracker (lowest seen in B)
    private int bCount = 0;

    PatternMatcher(String symbol) {
        this.symbol = symbol;
    }

    // Feed ticks in event-time order.
    void onTick(PriceTick tick) {
        BigDecimal p = tick.getPrice();
        switch (state) {
            case LOOKING_FOR_A:
                // Bind A to the current price as the starting reference.
                aPrice = p;
                lowPrice = null;
                bCount = 0;
                state = State.IN_B;
                log.fine(() -> symbol + " bind A=" + aPrice);
                break;
            case IN_B:
                if (p.compareTo(aPrice) < 0) {
                    // DEFINE B AS B.price < FIRST(A.price): stay in B (sustained low)
                    bCount++;
                    if (lowPrice == null || p.compareTo(lowPrice) < 0) lowPrice = p;
                    log.fine(() -> symbol + " B tick #" + bCount + " price=" + p);
                } else if (bCount > 0 && p.compareTo(aPrice) > 0) {
                    // DEFINE C AS C.price > FIRST(A.price): recovery -> MATCH complete
                    BigDecimal start = aPrice, low = lowPrice, recovery = p;
                    log.info(() -> "MATCH " + symbol + " [A B+ C] start=" + start
                            + " low=" + low + " recovery=" + recovery);
                    // AFTER MATCH SKIP PAST LAST ROW: restart, treat C as a new A.
                    aPrice = p; lowPrice = null; bCount = 0; // reseed
                } else {
                    // price returned to/above A without any B yet: reset A to this price
                    aPrice = p; lowPrice = null; bCount = 0;
                    log.fine(() -> symbol + " reset A=" + aPrice);
                }
                break;
        }
    }
}
