package com.bank.flink.mr;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: a price series forming drop→sustained low→recovery, and one
// that never recovers (no match).
public class MatchRecognizeDemo {
    private static final Logger log = Logger.getLogger(MatchRecognizeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new MrLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // RELIANCE: 2450 (A) -> 2440,2435,2438 (B+ below A) -> 2460 (C recovery) => MATCH
        PatternMatcher reliance = new PatternMatcher("RELIANCE");
        long t = 0;
        reliance.onTick(new PriceTick("RELIANCE", new BigDecimal("2450"), t += 1000));
        reliance.onTick(new PriceTick("RELIANCE", new BigDecimal("2440"), t += 1000));
        reliance.onTick(new PriceTick("RELIANCE", new BigDecimal("2435"), t += 1000));
        reliance.onTick(new PriceTick("RELIANCE", new BigDecimal("2438"), t += 1000));
        reliance.onTick(new PriceTick("RELIANCE", new BigDecimal("2460"), t += 1000)); // recovery

        // TCS: 3600 (A) -> 3580,3570 (B+ below A) -> never recovers => NO MATCH
        PatternMatcher tcs = new PatternMatcher("TCS");
        long u = 0;
        tcs.onTick(new PriceTick("TCS", new BigDecimal("3600"), u += 1000));
        tcs.onTick(new PriceTick("TCS", new BigDecimal("3580"), u += 1000));
        tcs.onTick(new PriceTick("TCS", new BigDecimal("3570"), u += 1000));
        log.info(() -> "TCS ended with no recovery -> no match emitted");
    }
}

// ─── Would be in MrLogFormatter.java in a real project ───
class MrLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
